func TestGenKeyRandBehaviour(t *testing.T) {
	var seed [SeedSize]byte
	for i := 0; i < SeedSize; i++ {
		seed[i] = byte(i + 1)
	}

	seedBuff := bytes.NewReader(seed[:])
	rnd := io.Reader(seedBuff)

	seed1 := make([]byte, ed25519.SeedSize)
	if _, err := io.ReadFull(rnd, seed1); err != nil {
		t.Fatalf("failed to read seed1: %v", err)
	}

	for i := 0; i < len(seed1); i++ {
		if seed1[i] != byte(i+1) {
			t.Fatalf("failed")
		}
	}

	seed2 := make([]byte, mldsa87.SeedSize)
	if _, err := io.ReadFull(rnd, seed2); err != nil {
		t.Fatalf("failed to read seed2: %v", err)
	}

	for i := ed25519.SeedSize; i < len(seed2); i++ {
		if seed2[i] != byte(i+1) {
			t.Fatalf("failed")
		}
	}

	seed3a := make([]byte, 32)
	_, err := rnd.Read(seed3a)
	if err != nil {
		t.Fatalf("failed to read seed3: %v", err)
	}
	for i := ed25519.SeedSize + mldsa87.SeedSize; i < len(seed3a); i++ {
		if seed3a[i] != byte(i+1) {
			t.Fatalf("failed")
		}
	}

	seed3b := make([]byte, 32)
	_, err = rnd.Read(seed3b)
	if err != nil {
		t.Fatalf("failed to read seed3: %v", err)
	}
	for i := ed25519.SeedSize + mldsa87.SeedSize + 32; i < len(seed3b); i++ {
		if seed3b[i] != byte(i+1) {
			t.Fatalf("failed")
		}
	}

	seed3c := make([]byte, 32)
	_, err = rnd.Read(seed3c)
	if err != nil {
		t.Fatalf("failed to read seed3: %v", err)
	}
	for i := ed25519.SeedSize + mldsa87.SeedSize + 32 + 32; i < len(seed3c); i++ {
		if seed3c[i] != byte(i+1) {
			t.Fatalf("failed")
		}
	}

}

func TestGenKey(t *testing.T) {
	pubKey, priKey, err := GenerateKey(rand.Reader)
	if err != nil {
		t.Fatalf("failed")
	}
	if pubKey == nil || priKey == nil {
		t.Fatalf("failed to generate key")
	}

	var seed1 [SeedSize]byte
	var seed3 [SeedSize]byte
	for i := 0; i < SeedSize; i++ {
		seed1[i] = byte(i)
		seed3[i] = byte(i + 1)
	}
	pubKey1, priKey1, err := NewKeyFromSeed(&seed1)
	if err != nil {
		t.Fatalf("failed")
	}
	pubKey2, priKey2, err := NewKeyFromSeed(&seed1)
	if err != nil {
		t.Fatalf("failed")
	}
	pubKey3, priKey3, err := NewKeyFromSeed(&seed3)
	if err != nil {
		t.Fatalf("failed")
	}

	if bytes.Compare(priKey1.key, priKey2.key) != 0 {
		t.Fatalf("private keys do not match")
	}

	if bytes.Compare(pubKey1.key, pubKey2.key) != 0 {
		t.Fatalf("public keys do not match")
	}
	if bytes.Compare(priKey2.key, priKey2.key) != 0 {
		t.Fatalf("private keys do not match")
	}
	if bytes.Compare(pubKey1.key, pubKey3.key) == 0 {
		t.Fatalf("public keys match")
	}
	if bytes.Compare(priKey2.key, priKey3.key) == 0 {
		t.Fatalf("private keys match")
	}
	pubKey4, priKey4, err := NewKeyFromSeed(&CommonSeed)
	if err != nil {
		t.Fatalf("failed")
	}
	if bytes.Compare(pubKey1.key, pubKey4.key) != 0 {
		t.Fatalf("public keys do not match")
	}
	if bytes.Compare(priKey2.key, priKey4.key) != 0 {
		t.Fatalf("private keys do not match")
	}
}

