func TestSignVerifyBasic(t *testing.T) {
	pubKey, priKey, err := NewKeyFromSeed(&CommonSeed)
	if err != nil {
		t.Fatalf("failed")
	}
	var msg [CRYPTO_MSG_LENGTH]byte
	for i := byte(0); i < CRYPTO_MSG_LENGTH; i++ {
		msg[i] = i
	}
	random := rand.Reader
	signature, err := Sign(priKey, random, msg[:])
	if err != nil {
		fmt.Println(err)
		t.Fatalf("failed")
	}

	if len(signature) != SigLength {
		t.Fatalf("failed")
	}

	if Verify(pubKey, msg[:], signature) == false {
		t.Fatalf("verify failed")
	}

	if Verify(pubKey, msg[:], signature[1:]) == true {
		t.Fatalf("verify passed unexpectedly")
	}

	//Message fuzz test
	var msg2 [CRYPTO_MSG_LENGTH]byte
	copy(msg2[:], msg[:])
	if Verify(pubKey, msg[:], signature) == false {
		t.Fatalf("verify failed")
	}
	for i := byte(0); i < CRYPTO_MSG_LENGTH; i++ {
		copy(msg2[:], msg[:])
		msg2[i] = msg2[i] + 1
		if Verify(pubKey, msg2[:], signature) == true {
			t.Fatalf("verify passed unexpectedly")
		}
	}

	//Signature fuzz test
	var signature2 [SigLength]byte
	copy(signature2[:], signature[:])
	if Verify(pubKey, msg[:], signature2[:]) == false {
		t.Fatalf("verify failed")
	}
	for i := 0; i < SigLength; i++ {
		copy(signature2[:], signature[:])
		signature2[i] = signature[i] + 1
		if Verify(pubKey, msg[:], signature2[:]) == true {
			t.Fatalf("verify passed unexpectedly")
		}
	}

	//public key fuzz test
	var publicFuzzBytes [PublicKeySize]byte
	copy(publicFuzzBytes[:], pubKey.key)
	var publicKeyFuzz *PublicKey
	publicKeyFuzz, err = UnmarshalPublicKey(publicFuzzBytes[:])
	if err != nil {
		t.Fatalf("failed")
	}

	if Verify(publicKeyFuzz, msg[:], signature) == false {
		t.Fatalf("verify failed")
	}
	for i := 0; i < PublicKeySize; i++ {
		copy(publicFuzzBytes[:], pubKey.key)
		publicFuzzBytes[i] = publicFuzzBytes[i] + 1
		publicKeyFuzz, err = UnmarshalPublicKey(publicFuzzBytes[:])
		if err != nil {
			t.Fatalf("failed")
		}

		if Verify(publicKeyFuzz, msg[:], signature) == true {
			t.Fatalf("verify passed unexpectedly")
		}
	}
}

func BenchmarkKeyGen(b *testing.B) {
	b.ResetTimer()
	for i := 0; i < BenchMarkIterations; i++ {
		_, _, err := GenerateKey(rand.Reader)
		if err != nil {
			b.Fatalf("failed")
		}
	}
}

func BenchmarkSign(b *testing.B) {
	b.ResetTimer()
	pubKey, priKey, err := NewKeyFromSeed(&CommonSeed)
	if err != nil {
		b.Fatalf("failed")
	}
	var msg [CRYPTO_MSG_LENGTH]byte
	for i := byte(0); i < CRYPTO_MSG_LENGTH; i++ {
		msg[i] = i
	}
	random := rand.Reader
	signature, err := Sign(priKey, random, msg[:])
	if err != nil {
		fmt.Println(err)
		b.Fatalf("failed")
	}
	if Verify(pubKey, msg[:], signature) == false {
		b.Fatalf("verify failed")
	}

	for i := 0; i <= BenchMarkIterations; i++ {
		signature, err = Sign(priKey, random, msg[:])
		if err != nil {
			fmt.Println(err)
			b.Fatalf("failed")
		}
	}
}

func TestPerf(t *testing.T) {
	if verifyFull() == false {
		t.Fatalf("failed")
	}
}

func verifyFull() bool {
	pubKey, priKey, err := NewKeyFromSeed(&CommonSeed)
	if err != nil {
		fmt.Println(err)
		return false
	}
	var msg [CRYPTO_MSG_LENGTH]byte
	for i := byte(0); i < CRYPTO_MSG_LENGTH; i++ {
		msg[i] = i
	}
	random := rand.Reader
	signature, err := Sign(priKey, random, msg[:])
	if err != nil {
		fmt.Println(err)
		return false
	}

	start := time.Now()
	for i := 0; i <= BenchMarkIterations; i++ {
		if Verify(pubKey, msg[:], signature) == false {
			return false
		}
	}
	duration := time.Since(start)
	fmt.Println("verifyFull Elapsed", duration, "iterations", BenchMarkIterations, "avg time ms", float64(duration.Milliseconds())/float64(BenchMarkIterations))
	return true
}

func BenchmarkVerify(b *testing.B) {
	b.ResetTimer()
	if verifyFull() == false {
		b.Fatalf("failed")
	}
}
